function hash(text){let h=2166136261>>>0;for(const c of String(text)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){let x=seed>>>0||1;return()=>{x=Math.imul(x^x>>>15,1|x);x^=x+Math.imul(x^x>>>7,61|x);return((x^x>>>14)>>>0)/4294967296}}
function camera(sc){const w=Number(sc?.width)||1800,h=Number(sc?.height)||1100;return{camX:Math.max(0,Math.min(Math.max(0,w-1600),(Number(state?.x)||800)-800)),camY:Math.max(0,Math.min(Math.max(0,h-1000),(Number(state?.y)||500)-500)),sx:.6,sy:.6}}
