  for(let i=0;i<8;i++){const a=-Math.PI/2+i*Math.PI/4,r=i%2?188:166;pylons.push({x:lair.x+Math.cos(a)*r,y:lair.y+Math.sin(a)*r,v:i%4,s:i%2?.92:1.04})}
