function blockFor(kind,p,i){if(['machine'].includes(kind))return{kind:'rect',x:p.x-66,y:p.y-48,w:132,h:96,id:kind+i};return{kind:'circle',x:p.x,y:p.y,r:kind==='rock'?30*(p.s||1):kind==='crystal'?25*(p.s||1):24,id:kind+i}}
