  sc.width=3000;sc.height=2200;sc.legendaryBiome=true;sc.legendaryType=meta.kind;sc.biome=meta.theme;sc.v112Theme=meta.theme;sc.v105dStyle=meta.theme;sc.routeKind=meta.theme;sc.v116Sanctuary=true;sc.v115Props=[];sc.v114Props=[];sc.grass=[];sc.obstacles=[];sc.mObstacles=[];buildRoad(sc,meta.entry);configureReturnExit(sc,meta.entry);
