function drawFlower(p,cam,kind){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx;if(q.x<-25||q.x>985||q.y<-25||q.y>625)return;ctx.save();shadow();ctx.fillStyle='#2f7e49';ctx.fillRect(q.x-2*s,q.y-13*s,4*s,18*s);const colors=kind==='light'?['#fff5a4','#ffe072','#fff']:kind==='air'?['#fff','#bcecff','#d9f8ff']:['#ff9fcb','#fff27a','#b7e6ff'];ctx.fillStyle=colors[p.v%colors.length];for(let a=0;a<4;a++){const ang=a*Math.PI/2;ctx.beginPath();ctx.arc(q.x+Math.cos(ang)*6*s,q.y-15*s+Math.sin(ang)*6*s,5*s,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#ffd25c';ctx.beginPath();ctx.arc(q.x,q.y-15*s,4*s,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawRock(p,cam,kind){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx;if(q.x<-50||q.x>1010||q.y<-50||q.y>650)return;ctx.save();shadow();const colors=kind==='fire'?['#2b292c','#4c3030']:kind==='storm'?['#536577','#758a94']:['#8d5d3d','#bc7e50'];ctx.fillStyle=colors[p.v%2];ctx.beginPath();ctx.moveTo(q.x-28*s,q.y);ctx.lineTo(q.x-20*s,q.y-30*s);ctx.lineTo(q.x+3*s,q.y-42*s);ctx.lineTo(q.x+30*s,q.y-18*s);ctx.lineTo(q.x+25*s,q.y+3*s);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(255,255,255,.2)';ctx.lineWidth=2*s;ctx.stroke();ctx.restore()}
function drawMachine(p,cam){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx;if(q.x<-90||q.x>1050||q.y<-110||q.y>710)return;ctx.save();shadow();if(p.v===2){for(let i=0;i<3;i++){const x=q.x+(i-1)*30*s;ctx.fillStyle=i%2?'#4d4240':'#5d4a3f';ctx.beginPath();ctx.roundRect(x-17*s,q.y-57*s,34*s,58*s,8*s);ctx.fill();ctx.strokeStyle='#9a704e';ctx.lineWidth=4*s;ctx.stroke();ctx.fillStyle='rgba(192,85,65,.55)';ctx.fillRect(x-15*s,q.y-35*s,30*s,8*s)}ctx.restore();return}if(p.v===3){ctx.strokeStyle='#2b2d31';ctx.lineWidth=20*s;ctx.beginPath();ctx.moveTo(q.x-45*s,q.y);ctx.lineTo(q.x-45*s,q.y-95*s);ctx.lineTo(q.x+38*s,q.y-95*s);ctx.lineTo(q.x+38*s,q.y-34*s);ctx.stroke();ctx.strokeStyle='#7b6c66';ctx.lineWidth=7*s;ctx.stroke();ctx.fillStyle='#a75bdb';ctx.beginPath();ctx.arc(q.x+38*s,q.y-31*s,10*s,0,Math.PI*2);ctx.fill();ctx.restore();return}const g=ctx.createLinearGradient(q.x-62*s,q.y-78*s,q.x+62*s,q.y);g.addColorStop(0,'#666268');g.addColorStop(.48,'#34363b');g.addColorStop(1,'#24262a');ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(q.x-62*s,q.y-78*s,124*s,82*s,11*s);ctx.fill();ctx.strokeStyle='#8b694d';ctx.lineWidth=5*s;ctx.stroke();ctx.fillStyle='#202227';ctx.beginPath();ctx.arc(q.x+21*s,q.y-39*s,18*s,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#7b7479';ctx.lineWidth=5*s;ctx.stroke();ctx.fillStyle='#b95cff';ctx.shadowColor='#b95cff';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(q.x-31*s,q.y-49*s,7*s,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#25262a';ctx.lineWidth=12*s;ctx.beginPath();ctx.moveTo(q.x-45*s,q.y-78*s);ctx.lineTo(q.x-45*s,q.y-109*s);ctx.lineTo(q.x+27*s,q.y-109*s);ctx.lineTo(q.x+27*s,q.y-82*s);ctx.stroke();ctx.strokeStyle='#d7a13d';ctx.lineWidth=4*s;for(let x=-54;x<50;x+=22){ctx.beginPath();ctx.moveTo(q.x+x*s,q.y-5*s);ctx.lineTo(q.x+(x+13)*s,q.y-22*s);ctx.stroke()}ctx.restore()}
function drawMushroom(p,cam){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx;if(q.x<-30||q.x>990||q.y<-40||q.y>640)return;ctx.save();shadow();ctx.fillStyle='#d8e4c4';ctx.fillRect(q.x-4*s,q.y-20*s,8*s,22*s);ctx.fillStyle=p.v%2?'#9d5bc4':'#45cfa3';ctx.beginPath();ctx.ellipse(q.x,q.y-22*s,18*s,11*s,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(245,255,211,.72)';ctx.beginPath();ctx.arc(q.x-6*s,q.y-26*s,2.5*s,0,Math.PI*2);ctx.arc(q.x+6*s,q.y-23*s,2*s,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawCrystal(p,cam,kind){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx;if(q.x<-35||q.x>995||q.y<-55||q.y>655)return;ctx.save();shadow();ctx.fillStyle=kind==='origin'?['#82d6a6','#a98cdd','#ffd885'][p.v%3]:'#c8f7ff';ctx.strokeStyle='rgba(255,255,255,.75)';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(q.x,q.y-47*s);ctx.lineTo(q.x+18*s,q.y-14*s);ctx.lineTo(q.x+11*s,q.y+2*s);ctx.lineTo(q.x-14*s,q.y+2*s);ctx.lineTo(q.x-18*s,q.y-15*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}
function drawPool(p,cam){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx,t=performance.now()/500;if(q.x<-75||q.x>1035||q.y<-45||q.y>645)return;ctx.save();shadow();ctx.fillStyle='rgba(25,62,58,.86)';ctx.beginPath();ctx.ellipse(q.x,q.y,62*s,32*s,.12,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(92,246,214,.55)';ctx.lineWidth=3*s;ctx.stroke();ctx.strokeStyle='rgba(209,137,255,.5)';ctx.lineWidth=2*s;ctx.beginPath();ctx.ellipse(q.x+Math.sin(t+p.x)*9*s,q.y,35*s,14*s,.12,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawVolcano(sc,cam){const v=sc.v116Features.volcano,q=screen(v.x,v.y+80,cam),s=cam.sx;ctx.save();shadow();ctx.fillStyle='rgba(31,18,20,.42)';ctx.beginPath();ctx.ellipse(q.x,q.y+92*s,292*s,52*s,0,0,Math.PI*2);ctx.fill();const g=ctx.createLinearGradient(q.x,q.y-210*s,q.x,q.y+100*s);g.addColorStop(0,'#6b3b34');g.addColorStop(.5,'#432d2e');g.addColorStop(1,'#241f24');ctx.fillStyle=g;ctx.strokeStyle='#1b171b';ctx.lineWidth=12*s;ctx.beginPath();ctx.moveTo(q.x-286*s,q.y+92*s);ctx.quadraticCurveTo(q.x-205*s,q.y-20*s,q.x-110*s,q.y-164*s);ctx.quadraticCurveTo(q.x-76*s,q.y-210*s,q.x-38*s,q.y-182*s);ctx.quadraticCurveTo(q.x,q.y-164*s,q.x+38*s,q.y-182*s);ctx.quadraticCurveTo(q.x+78*s,q.y-210*s,q.x+112*s,q.y-162*s);ctx.quadraticCurveTo(q.x+205*s,q.y-16*s,q.x+286*s,q.y+92*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#f05a24';ctx.shadowColor='#ff6b28';ctx.shadowBlur=13;ctx.lineWidth=9*s;for(const off of[-52,36]){ctx.beginPath();ctx.moveTo(q.x+off*s,q.y-158*s);ctx.bezierCurveTo(q.x+(off-24)*s,q.y-88*s,q.x+(off+18)*s,q.y-40*s,q.x+(off-5)*s,q.y+42*s);ctx.stroke()}ctx.shadowBlur=0;ctx.fillStyle='#1e1c20';ctx.beginPath();ctx.ellipse(q.x,q.y-181*s,94*s,29*s,0,0,Math.PI*2);ctx.fill();const glow=.65+.18*Math.sin(performance.now()/260);ctx.fillStyle=`rgba(255,89,24,${glow})`;ctx.beginPath();ctx.ellipse(q.x,q.y-181*s,66*s,15*s,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawBridge(sc,cam){const b=sc.v116Features.bridge,p=screen(b.x,b.y,cam);ctx.save();shadow();ctx.fillStyle='#6e4d31';ctx.beginPath();ctx.roundRect(p.x,p.y,b.w*cam.sx,b.h*cam.sy,10);ctx.fill();ctx.strokeStyle='#d0a069';ctx.lineWidth=4;ctx.stroke();ctx.strokeStyle='rgba(52,32,22,.66)';ctx.lineWidth=2;for(let x=0;x<b.w;x+=34){ctx.beginPath();ctx.moveTo(p.x+x*cam.sx,p.y);ctx.lineTo(p.x+x*cam.sx,p.y+b.h*cam.sy);ctx.stroke()}ctx.restore()}
