function shrinePalette(kind){return{
  nature:['#315e37','#8ac866','#f6cf65'],fire:['#241e23','#a84328','#ff9a2e'],water:['#276f7d','#70c8bd','#f0d89d'],storm:['#394b5d','#8ca6b3','#f2d75f'],factory:['#282a30','#786b64','#c15ee7'],rock:['#72503a','#b98255','#edc783'],air:['#739da6','#d9edf0','#ffffff'],spore:['#28483e','#6dc8a3','#b86bd0'],ice:['#75aebd','#c9f2f5','#ffffff'],light:['#ad8b3d','#f3db72','#fff6c4'],origin:['#59646d','#9d86cf','#78d8b5']
}[kind]||['#44545c','#aebec4','#ffffff']}
function drawShrineBase(sc,meta,cam){const l=sc.v116Lair,q=screen(l.x,l.y,cam),p=shrinePalette(meta.kind),sx=cam.sx,sy=cam.sy;ctx.save();ctx.globalAlpha=.96;ctx.fillStyle=p[0]+'cc';ctx.beginPath();ctx.ellipse(q.x,q.y+12*sy,154*sx,72*sy,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=p[1];ctx.lineWidth=10*sx;ctx.stroke();ctx.strokeStyle=p[2];ctx.lineWidth=3*sx;ctx.beginPath();ctx.ellipse(q.x,q.y+12*sy,112*sx,50*sy,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.62;ctx.lineWidth=4*sx;for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.beginPath();ctx.moveTo(q.x+Math.cos(a)*48*sx,q.y+12*sy+Math.sin(a)*22*sy);ctx.lineTo(q.x+Math.cos(a)*136*sx,q.y+12*sy+Math.sin(a)*62*sy);ctx.stroke()}ctx.restore()}
function drawShrineAsset(p,meta,cam,accent=false){const q=screen(p.x,p.y,cam),s=(p.s||1)*cam.sx,c=shrinePalette(meta.kind);if(q.x<-70||q.x>1030||q.y<-90||q.y>690)return;ctx.save();shadow();ctx.lineCap='round';ctx.lineJoin='round';
  if(meta.kind==='nature'){
    ctx.strokeStyle='#6f4b2e';ctx.lineWidth=(accent?7:12)*s;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.quadraticCurveTo(q.x-10*s,q.y-34*s,q.x+(p.v%2?12:-12)*s,q.y-58*s);ctx.stroke();ctx.fillStyle=p.v%2?'#72b956':'#3d8d4f';for(const dx of[-12,0,13]){ctx.beginPath();ctx.ellipse(q.x+dx*s,q.y-(48+Math.abs(dx))*s,13*s,9*s,dx*.04,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#ffd976';ctx.beginPath();ctx.arc(q.x+(p.v-1.5)*4*s,q.y-65*s,4*s,0,Math.PI*2);ctx.fill()
  }else if(meta.kind==='fire'){
    ctx.fillStyle=accent?'#413035':'#211f24';ctx.strokeStyle='#8f3d2c';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(q.x,q.y-68*s);ctx.lineTo(q.x+20*s,q.y-14*s);ctx.lineTo(q.x+12*s,q.y+2*s);ctx.lineTo(q.x-18*s,q.y+2*s);ctx.lineTo(q.x-23*s,q.y-18*s);ctx.closePath();ctx.fill();ctx.stroke();if(p.v%2===0){ctx.fillStyle='#ff8a28';ctx.beginPath();ctx.moveTo(q.x,q.y-56*s);ctx.quadraticCurveTo(q.x+18*s,q.y-31*s,q.x,q.y-20*s);ctx.quadraticCurveTo(q.x-18*s,q.y-31*s,q.x,q.y-56*s);ctx.fill()}
  }else if(meta.kind==='water'){
    ctx.strokeStyle=p.v%2?'#ef8f80':'#6cc8b9';ctx.lineWidth=(accent?6:9)*s;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x,q.y-50*s);ctx.moveTo(q.x,q.y-31*s);ctx.lineTo(q.x-18*s,q.y-48*s);ctx.moveTo(q.x+1*s,q.y-39*s);ctx.lineTo(q.x+18*s,q.y-58*s);ctx.stroke();ctx.fillStyle='#fff2cf';ctx.beginPath();ctx.ellipse(q.x,q.y-6*s,20*s,9*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bdeaff';ctx.beginPath();ctx.arc(q.x,q.y-9*s,5*s,0,Math.PI*2);ctx.fill()
  }else if(meta.kind==='storm'){
    ctx.strokeStyle='#344451';ctx.lineWidth=(accent?7:11)*s;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x,q.y-76*s);ctx.stroke();ctx.strokeStyle='#d6974c';ctx.lineWidth=4*s;for(let y=18;y<58;y+=11){ctx.beginPath();ctx.arc(q.x,q.y-y*s,10*s,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#f6df65';ctx.beginPath();ctx.moveTo(q.x,q.y-89*s);ctx.lineTo(q.x+9*s,q.y-73*s);ctx.lineTo(q.x-9*s,q.y-73*s);ctx.closePath();ctx.fill()
  }else if(meta.kind==='factory'){
    ctx.fillStyle=p.v%2?'#4b4548':'#34373c';ctx.strokeStyle='#8b7467';ctx.lineWidth=4*s;ctx.beginPath();ctx.roundRect(q.x-28*s,q.y-62*s,56*s,64*s,7*s);ctx.fill();ctx.stroke();ctx.fillStyle=p.v%3?'#b55cdb':'#db784c';ctx.fillRect(q.x-18*s,q.y-49*s,36*s,9*s);ctx.fillStyle='#1e2226';ctx.fillRect(q.x-18*s,q.y-31*s,36*s,22*s);ctx.strokeStyle='#958b87';ctx.lineWidth=5*s;ctx.beginPath();ctx.moveTo(q.x+26*s,q.y-48*s);ctx.lineTo(q.x+43*s,q.y-48*s);ctx.lineTo(q.x+43*s,q.y-7*s);ctx.stroke()
  }else if(meta.kind==='rock'){
    ctx.fillStyle=p.v%2?'#8c6040':'#6d4b38';ctx.strokeStyle='#d3a46e';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(q.x-22*s,q.y);ctx.lineTo(q.x-17*s,q.y-67*s);ctx.lineTo(q.x,q.y-82*s);ctx.lineTo(q.x+20*s,q.y-64*s);ctx.lineTo(q.x+24*s,q.y);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#f0cf8d';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(q.x-8*s,q.y-45*s);ctx.lineTo(q.x+9*s,q.y-31*s);ctx.moveTo(q.x+9*s,q.y-50*s);ctx.lineTo(q.x-7*s,q.y-29*s);ctx.stroke()
  }else if(meta.kind==='air'){
    ctx.fillStyle='#d9eef0';ctx.strokeStyle='#7faab4';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(q.x,q.y-76*s);ctx.lineTo(q.x+17*s,q.y-20*s);ctx.lineTo(q.x+10*s,q.y);ctx.lineTo(q.x-12*s,q.y);ctx.lineTo(q.x-18*s,q.y-20*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='rgba(255,255,255,.82)';ctx.beginPath();ctx.arc(q.x-17*s,q.y-8*s,13*s,0,Math.PI*2);ctx.arc(q.x,q.y-12*s,18*s,0,Math.PI*2);ctx.arc(q.x+19*s,q.y-7*s,12*s,0,Math.PI*2);ctx.fill()
  }else if(meta.kind==='spore'){
    ctx.fillStyle='#d9e5c8';ctx.fillRect(q.x-7*s,q.y-38*s,14*s,40*s);ctx.fillStyle=p.v%2?'#a45fc1':'#48c79d';ctx.beginPath();ctx.ellipse(q.x,q.y-42*s,31*s,18*s,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#eaffc4';for(const dx of[-13,0,14]){ctx.beginPath();ctx.arc(q.x+dx*s,q.y-(45+Math.abs(dx%3))*s,3*s,0,Math.PI*2);ctx.fill()}
  }else if(meta.kind==='ice'){
    ctx.fillStyle=p.v%2?'#b8edf2':'#d9fbff';ctx.strokeStyle='#ffffff';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(q.x,q.y-84*s);ctx.lineTo(q.x+21*s,q.y-18*s);ctx.lineTo(q.x+10*s,q.y+2*s);ctx.lineTo(q.x-18*s,q.y+2*s);ctx.lineTo(q.x-24*s,q.y-17*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#7ebccb';ctx.beginPath();ctx.moveTo(q.x,q.y-72*s);ctx.lineTo(q.x-6*s,q.y-9*s);ctx.stroke()
  }else if(meta.kind==='light'){
    ctx.strokeStyle='#a47d32';ctx.lineWidth=9*s;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x,q.y-55*s);ctx.stroke();ctx.fillStyle='#fff1a0';ctx.strokeStyle='#e4b94c';ctx.lineWidth=4*s;ctx.beginPath();ctx.ellipse(q.x,q.y-67*s,27*s,18*s,-.25,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#ffffff';ctx.beginPath();ctx.arc(q.x-7*s,q.y-72*s,6*s,0,Math.PI*2);ctx.fill()
  }else{
    ctx.fillStyle=[c[1],c[2],'#f3d780'][p.v%3];ctx.strokeStyle='#f4f1ff';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(q.x,q.y-80*s);ctx.lineTo(q.x+21*s,q.y-19*s);ctx.lineTo(q.x+9*s,q.y+2*s);ctx.lineTo(q.x-16*s,q.y+2*s);ctx.lineTo(q.x-22*s,q.y-18*s);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='rgba(228,218,255,.75)';ctx.lineWidth=3*s;ctx.beginPath();ctx.arc(q.x,q.y-35*s,31*s,0,Math.PI*2);ctx.stroke()
  }ctx.restore()}
